CREATE TYPE "Role" AS ENUM ('user','moderator','admin');
CREATE TYPE "UserStatus" AS ENUM ('active','suspended','pending');
CREATE TYPE "Plan" AS ENUM ('FREE','DEVELOPER','PRO','ENTERPRISE');
CREATE TABLE "User" ("id" TEXT NOT NULL,"username" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'user',"status" "UserStatus" NOT NULL DEFAULT 'active',"plan" "Plan" NOT NULL DEFAULT 'FREE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastLogin" TIMESTAMP(3),CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ApiKey" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"prefix" VARCHAR(20) NOT NULL,"keyHash" TEXT NOT NULL,"userId" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastUsedAt" TIMESTAMP(3),"requestCount" BIGINT NOT NULL DEFAULT 0,CONSTRAINT "ApiKey_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RequestLog" ("id" TEXT NOT NULL,"userId" TEXT,"apiKeyId" TEXT,"endpoint" TEXT NOT NULL,"method" TEXT NOT NULL,"statusCode" INTEGER NOT NULL,"durationMs" INTEGER NOT NULL,"ipHash" TEXT,"userAgent" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RequestLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PasswordResetToken" ("id" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "ApiKey_keyHash_key" ON "ApiKey"("keyHash"); CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash");
CREATE INDEX "ApiKey_userId_active_idx" ON "ApiKey"("userId","active"); CREATE INDEX "RequestLog_createdAt_idx" ON "RequestLog"("createdAt"); CREATE INDEX "RequestLog_endpoint_createdAt_idx" ON "RequestLog"("endpoint","createdAt"); CREATE INDEX "RequestLog_userId_createdAt_idx" ON "RequestLog"("userId","createdAt"); CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
ALTER TABLE "ApiKey" ADD CONSTRAINT "ApiKey_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RequestLog" ADD CONSTRAINT "RequestLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "RequestLog" ADD CONSTRAINT "RequestLog_apiKeyId_fkey" FOREIGN KEY ("apiKeyId") REFERENCES "ApiKey"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PasswordResetToken" ADD CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
